-- 自我檢查：筆數與分布跟產生時一樣
DO $$
DECLARE got TEXT;
BEGIN
  SELECT string_agg(stat_key || ' ' || n, '、' ORDER BY stat_key) INTO got
    FROM (SELECT stat_key, count(*) AS n FROM policy_jp.stat_registry WHERE year = 2025 GROUP BY stat_key) t;
  IF got IS DISTINCT FROM 'aging_rate 1959、area_km2 1959、population 1959' THEN
    RAISE EXCEPTION 'stat_registry 的分布不對：%（預期 aging_rate 1959、area_km2 1959、population 1959）', got;
  END IF;
END
$$;
